// stores/counter.ts
import { writable } from "svelte/store";

export const counter = writable(0);

export function increment() {
  counter.update((n) => n + 1);
}

export function reset() {
  counter.set(0);
}

// actions/clickOutside.ts
import type { Action } from "svelte/action";

export const clickOutside: Action<HTMLElement, (e: MouseEvent) => void> = (node, callback) => {
  const handle = (e: MouseEvent) => {
    if (!node.contains(e.target as Node)) callback?.(e);
  };
  document.addEventListener("click", handle, true);
  return {
    update(newCb) { callback = newCb; },
    destroy() { document.removeEventListener("click", handle, true); }
  };
};

// src/routes/users/[id]/+page.server.ts
import { error } from "@sveltejs/kit";
import type { PageServerLoad } from "./$types";

export const load: PageServerLoad = async ({ params, fetch }) => {
  const res = await fetch(`/api/users/${params.id}`);
  if (!res.ok) throw error(404, "User not found");
  const user = await res.json();
  return { user };
};

// src/routes/signup/+page.server.ts
import { fail, redirect } from "@sveltejs/kit";
import type { Actions } from "./$types";

export const actions: Actions = {
  default: async ({ request }) => {
    const data = await request.formData();
    const email = String(data.get("email") ?? "");
    const password = String(data.get("password") ?? "");

    if (!email.includes("@")) {
      return fail(400, { email, error: "Invalid email" });
    }
    if (password.length < 8) {
      return fail(400, { email, error: "Password too short" });
    }

    // create user...
    throw redirect(303, "/welcome");
  }
};

// src/hooks.server.ts
import type { Handle } from "@sveltejs/kit";
import { verifySession } from "$lib/server/auth";

export const handle: Handle = async ({ event, resolve }) => {
  const session = event.cookies.get("session");
  if (session) {
    const user = await verifySession(session);
    if (user) event.locals.user = user;
    else event.cookies.delete("session", { path: "/" });
  }
  return resolve(event);
};

